export default function build({ THREE, traits, ui, isGrabbed, assets }) {
  const root = new THREE.Group();

  const gears = assets.get('gear-train-trellis');
  root.add(gears.object3D);
  gears.object3D.scale.setScalar(1.5);

  // Labels (create once, show only the ones for the current step)
  const labelText = {
    drive_gear: 'Drive gear (input)',
    driven_gear: 'Driven gear (output)',
    crank_handle: 'Crank handle',
    axle: 'Axle',
    base_plate: 'Base plate',
    axle_support: 'Axle support',
  };
  const labels = {};
  Object.keys(labelText).forEach((id) => {
    labels[id] = gears.label(id, labelText[id]);
    labels[id].setVisible(false);
  });

  const steps = [
    {
      title: '1. Input and output',
      body: 'You turn the crank, which spins the drive gear (input). Its teeth push on the driven gear, which delivers the output.',
      labels: ['drive_gear', 'driven_gear', 'crank_handle', 'base_plate'],
      glow: 'drive_gear',
    },
    {
      title: '2. Teeth mesh',
      body: 'Meshed teeth move at the same speed at the contact point. The two gears turn in opposite directions.',
      labels: ['drive_gear', 'driven_gear', 'axle', 'axle_support'],
      glow: 'driven_gear',
    },
    {
      title: '3. Speed',
      body: 'Gear ratio = driven teeth / drive teeth. A bigger driven gear has more teeth, so it turns slower. Output speed = input speed / ratio.',
      labels: ['drive_gear', 'driven_gear'],
      glow: 'driven_gear',
    },
    {
      title: '4. Turning force',
      body: 'What you lose in speed you gain in torque (turning force). Ratio 2:1 gives half the speed and double the torque. Power stays the same, apart from friction.',
      labels: ['drive_gear', 'driven_gear', 'crank_handle'],
      glow: 'driven_gear',
    },
    {
      title: '5. Try it',
      body: 'Pick a driven gear size in the side panel and watch speed and torque change. Pinch a gear to pull it out and look closer.',
      labels: ['drive_gear', 'driven_gear'],
      glow: null,
    },
  ];

  const main = ui(`
    <style>
      .card { width: 520px; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .step { color: #8fb8ff; font-size: 22px; }
      .body { color: #d7dbe2; font-size: 24px; }
      .row { flex-direction: row; gap: 10px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
              border-radius: 12px; background-color: #444a55; }
      .bt { color: #ffffff; font-size: 22px; font-weight: 700; }
      .credit { color: #9aa1ad; font-size: 18px; }
    </style>
    <div class="card">
      <span class="step" id="step">Step 1 of 5</span>
      <span class="title" id="title">Title</span>
      <span class="body" id="body">Body</span>
      <div class="row">
        <button class="btn" id="back"><span class="bt">Back</span></button>
        <button class="btn" id="next"><span class="bt">Next</span></button>
      </div>
      <div class="row">
        <button class="btn2" id="explode"><span class="bt">Explode</span></button>
        <button class="btn2" id="xray"><span class="bt">X-ray</span></button>
        <button class="btn2" id="reset"><span class="bt">Reset</span></button>
      </div>
      <span class="credit">Generated 3D model: tooth counts here are example values, not measured from it. ${gears.credit || ''}</span>
    </div>`, { width: 0.38, position: [0, 0.46, 0] });
  root.add(main.object3D);

  const calc = ui(`
    <style>
      .card { width: 420px; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .res { color: #ffd166; font-size: 24px; font-weight: 700; }
      .row { flex-direction: row; gap: 8px; }
      .b { padding-top: 10px; padding-bottom: 10px; padding-left: 12px; padding-right: 12px;
           border-radius: 12px; background-color: #444a55; }
      .bt { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Ratio lab</span>
      <span class="body">Drive gear: 20 teeth, 60 rpm, 10 Nm of torque. Choose the driven gear:</span>
      <div class="row">
        <button class="b" id="t10"><span class="bt">10 teeth</span></button>
        <button class="b" id="t20"><span class="bt">20 teeth</span></button>
        <button class="b" id="t40"><span class="bt">40 teeth</span></button>
      </div>
      <span class="res" id="ratio">Ratio 1 : 1</span>
      <span class="res" id="speed">Speed 60 rpm</span>
      <span class="res" id="torque">Torque 10 Nm</span>
      <span class="body" id="note">Same size gears: same speed and torque, opposite direction.</span>
    </div>`, { width: 0.3, position: [0.42, 0.22, 0] });
  root.add(calc.object3D);

  const notes = {
    10: 'Smaller driven gear: faster output, less torque. Good for speed.',
    20: 'Same size gears: same speed and torque, opposite direction.',
    40: 'Bigger driven gear: slower output, more torque. Good for lifting heavy loads.',
  };
  function pick(n) {
    const ratio = n / 20;
    const rpm = 1200 / n;
    const torque = (10 * n) / 20;
    calc.set('ratio', { text: 'Ratio ' + (n === 10 ? '1 : 2' : n === 20 ? '1 : 1' : '2 : 1') + ' (driven : drive)' });
    calc.set('speed', { text: 'Speed ' + Math.round(rpm) + ' rpm' });
    calc.set('torque', { text: 'Torque ' + Math.round(torque) + ' Nm' });
    calc.set('note', { text: notes[n] });
    [10, 20, 40].forEach((k) => calc.set('t' + k, { backgroundColor: k === n ? '#2f6fdb' : '#444a55' }));
  }
  calc.on('t10', 'click', () => pick(10));
  calc.on('t20', 'click', () => pick(20));
  calc.on('t40', 'click', () => pick(40));
  pick(20);

  let stepIndex = 0;
  let xray = false;
  let explodeTarget = 0;
  let explodeAmt = 0;

  function applyXray() {
    if (xray) gears.xray(true, ['drive_gear', 'driven_gear']);
    else gears.xray(false);
  }

  function showStep() {
    const s = steps[stepIndex];
    main.set('step', { text: 'Step ' + (stepIndex + 1) + ' of ' + steps.length });
    main.set('title', { text: s.title });
    main.set('body', { text: s.body });
    Object.keys(labels).forEach((id) => labels[id].setVisible(s.labels.indexOf(id) >= 0));
    gears.highlight(s.glow);
  }
  showStep();

  main.on('next', 'click', () => { stepIndex = Math.min(steps.length - 1, stepIndex + 1); showStep(); });
  main.on('back', 'click', () => { stepIndex = Math.max(0, stepIndex - 1); showStep(); });
  main.on('explode', 'click', () => {
    explodeTarget = explodeTarget > 0 ? 0 : 0.6;
    main.set('explode', { backgroundColor: explodeTarget > 0 ? '#2f6fdb' : '#444a55' });
  });
  main.on('xray', 'click', () => {
    xray = !xray;
    applyXray();
    main.set('xray', { backgroundColor: xray ? '#2f6fdb' : '#444a55' });
  });
  main.on('reset', 'click', () => {
    xray = false;
    explodeTarget = 0;
    explodeAmt = 0;
    gears.reset();
    main.set('explode', { backgroundColor: '#444a55' });
    main.set('xray', { backgroundColor: '#444a55' });
    showStep();
  });

  // Let the learner pick up each gear; pressing one makes it glow
  traits(gears.part('drive_gear'), { grab: true, onPress: () => gears.highlight('drive_gear') });
  traits(gears.part('driven_gear'), { grab: true, onPress: () => gears.highlight('driven_gear') });

  return {
    root,
    update(time, delta) {
      const d = explodeTarget - explodeAmt;
      if (Math.abs(d) > 0.001) {
        explodeAmt += d * Math.min(1, delta * 4);
        gears.explode(explodeAmt);
      }
    },
  };
}
